// ---- Voz clonada (ElevenLabs) ----
// Llama al endpoint serverless /api/tts (que vive fuera de este componente, en Vercel)
// donde se guarda la API key de ElevenLabs de forma segura y se usa tu Voice ID clonado.
// Si el endpoint no existe o falla (por ejemplo, corriendo en el preview de Claude.ai,
// donde no hay backend), devuelve false y el que llama usa la voz nativa del navegador
// (SpeechSynthesisUtterance) como respaldo automático.
let _elevenAudio = null;
async function elevenSpeak(text, onEnd) {
  try {
    const res = await fetch("/api/tts", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ text }),
    });
    if (!res.ok) return false;
    const blob = await res.blob();
    if (!blob || blob.size === 0) return false;
    const url = URL.createObjectURL(blob);
    if (_elevenAudio) {
      try { _elevenAudio.pause(); } catch (e) {}
    }
    _elevenAudio = new Audio(url);
    if (onEnd) _elevenAudio.onended = onEnd;
    await _elevenAudio.play();
    return true;
  } catch (e) {
    return false;
  }
}

// Helper para dibujar rectángulos redondeados en canvas
function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

const saveGame = (data) => {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } catch (e) {}
};

const loadGame = () => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  } catch (e) { return null; }
};

