// AudioContext persistente que se desbloquea con el primer toque
let _ctx = null;
const getAudioCtx = () => {
  if (!_ctx) {
    _ctx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (_ctx.state === "suspended") {
    _ctx.resume();
  }
  if (_ctx.state === "interrupted") {
    _ctx.resume();
  }
  return _ctx;
};

const playBeep = (freq, type, duration, volume) => {
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(ctx.destination);
    osc.type = type || "sine";
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(volume || 0.18, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + duration);
  } catch(e) {}
};

function SlotNumber({ value, color, fontSize = 64 }) {
  const [display, setDisplay] = useState(value);
  const [rolling, setRolling] = useState(false);
  const [prev, setPrev] = useState(value);

  const playTick = (count) => {
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(ctx.destination);
      osc.type = "triangle";
      const freq = 200 + (count / 11) * 600;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.18, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.05);
    } catch(e) {}
  };

  useEffect(() => {
    if (value === prev) return;
    setPrev(value);
    setRolling(true);
    let count = 0;
    const interval = setInterval(() => {
      setDisplay(Math.floor(Math.random() * 99));
      playTick(count);
      count++;
      if (count >= 12) {
        clearInterval(interval);
        setDisplay(value);
        setRolling(false);
      }
    }, 55);
    return () => clearInterval(interval);
  }, [value]);

  return (
    <div style={{
      fontFamily: "'Orbitron', sans-serif",
      fontSize: fontSize, fontWeight: 900,
      color: rolling ? "#FFD700" : color,
      lineHeight: "1", textAlign: "center",
      display:"flex", alignItems:"center", justifyContent:"center",
      letterSpacing: 1,
      textShadow: rolling
        ? "0 0 10px #FFD700, 0 0 22px #FFD700aa"
        : `0 0 10px ${color}, 0 0 22px ${color}aa, 0 0 40px ${color}66`,
      transition: "color 0.2s",
    }}>
      {display}
    </div>
  );
}

